<?php
namespace App\Http\Controllers\Demo\Admin;
use App\Http\Controllers\Controller; use App\Http\Requests\ServiceRequest; use App\Models\Service; use Illuminate\Http\RedirectResponse; use Illuminate\View\View;
class ServiceController extends Controller { private function find(int$id):Service{return Service::where('shop_id',auth()->user()->shop_id)->findOrFail($id);} public function index():View{return view('demo.admin.services.index',['services'=>auth()->user()->shop->services()->orderBy('display_order')->get()]);} public function store(ServiceRequest$r):RedirectResponse{auth()->user()->shop->services()->create($r->validated()+['is_active'=>$r->boolean('is_active')]);return back()->with('success','メニューを追加しました。');} public function update(ServiceRequest$r,int$service):RedirectResponse{$this->find($service)->update($r->validated()+['is_active'=>$r->boolean('is_active')]);return back()->with('success','メニューを更新しました。');} public function destroy(int$service):RedirectResponse{$this->find($service)->delete();return back()->with('success','メニューを非表示にしました。');} }
